(7215659, 1111735, 114285, '<td valign="top">My first entry was a bike shot, should''ve kept it in, I love all the squiggly patterns around the handle bars, bumping up, in my top ten.</td>', 'My first entry was a bike shot, should''ve kept it in, I love all the squiggly patterns around the handle bars, bumping up, in my top ten.', '2014-05-11 23:43:10.000000', NULL, 1),
(7215666, 1111667, 104230, '<td valign="top">Very clever. Well conceived and executed. I''m guessing this was taken by Wendy in one of W&amp;M''s buildings.</td>', 'Very clever. Well conceived and executed. I''m guessing this was taken by Wendy in one of W&M''s buildings.', '2014-05-12 00:53:53.000000', NULL, 1),
(7215681, 1111607, 97225, '<td valign="top">Congratulations, Paul. Wonderful shot, I love everything about it. Love, the ''eye contact'' somehow not expected from a reflection, lol.</td>', 'Congratulations, Paul. Wonderful shot, I love everything about it. Love, the ''eye contact'' somehow not expected from a reflection, lol.', '2014-05-12 01:09:53.000000', NULL, 0),
